INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(103378, 'ruRU', '', 'Двадцать пять золотых за этот бриллиант бриллиантов? Не думаю.$b$bНо у тебя мудрое лицо. Полагаю, я мог бы расстаться с ним за двести золотых.', 24330),
(103379, 'ruRU', '', 'Я начал этот торг с тобой не для того, чтобы меня оскорбляли. Двести пятьдесят — моё последнее предложение, соглашайся или уходи.$b$bКонечно, вариант с услугой всё ещё на столе, если предпочитаешь этот путь.', 24330),
(103380, 'ruRU', '', 'Ты повышаешь, а мне полагается снижать, да? Торг, который мне слишком хорошо знаком.$b$bЧто ж, спущусь до ста семидесяти пяти, соглашайся или уходи.$b$bКонечно, вариант с услугой всё ещё на столе, если предпочитаешь этот путь.', 24330),
(103381, 'ruRU', '', 'Не нужно разговаривать со мной таким тоном, $gсэр:мадам;. Печально вести дела с тем, у кого так мало денег.$b$bРазорят ли тебя сто двадцать пять золотых?', 24330),
(103382, 'ruRU', '', 'Да брось, неужели ты настолько беден?$b$bЛадно, спущу ещё немного. Как насчёт ровно ста золотых? Справедливая цена за прекраснейший из бриллиантов.', 24330),
(103383, 'ruRU', '', 'И, пожалуй, на этом мой торг окончен.$b$bСто двадцать золотых, соглашайся или уходи.$b$bКонечно, вариант с услугой всё ещё на столе, если предпочитаешь этот путь.', 24330),
(103384, 'ruRU', '', 'Если бы ты не был таким обаяшкой, я бы закончил этот торг, даже не начав его.$b$bНо ты мне нравишься. Ты довольно упрям и хорошо торгуешься.$b$bПо рукам за пятьдесят.', 24330),
(103385, 'ruRU', '', 'Что ж, самая честная цена, которую ты от меня услышишь — сто золотых, соглашайся или уходи.$b$bКонечно, вариант с услугой всё ещё на столе, если предпочитаешь этот путь.', 24330),
(103396, 'ruRU', '', 'А вот и твой бриллиант. Приятно было иметь с тобой дело. Пожалуйста, возвращайся поскорее.', 24330),
(103401, 'ruRU', '', 'Ёлки! Убирайтесь отсюда! Пошли вон!', 24330),
(103402, 'ruRU', '', 'Откуда они взялись?', 24330),
(103403, 'ruRU', '', 'Обратно в Пустоту, прочь!', 24330),
(103404, 'ruRU', '', 'Этот мой!', 24330),
(103405, 'ruRU', '', 'Твоё присутствие здесь нежелательно!', 24330),
(103417, 'ruRU', '', 'Остальные... Я немедленно их предупрежу!', 24330),
(103418, 'ruRU', '', 'Не пускайте их за ворота!', 24330),
(103419, 'ruRU', '', 'Они были здесь всё это время!', 24330),
(103422, 'ruRU', '', 'Зиннин, берегись!', 24330),
(103426, 'ruRU', '', 'Мы отомстим за тебя! Нужно с этим покончить. За чудовищем!', 24330),
(103430, 'ruRU', '', 'Эти раны... они не заживают. Нужно покончить с этим быстро, пока мы не истекли кровью!', 24330),
(103431, 'ruRU', '', 'Зиннин...', 24330),
(103432, 'ruRU', '', 'Убей... чудовище. Найди... Когтекрыла...', 24330),
(103434, 'ruRU', '', 'Что ты наделал? Хссс...', 24330),
(103435, 'ruRU', '', 'Госпожа Приливов! Они меня ослабляют!', 24330),
(103436, 'ruRU', '', 'Что ты... Хссс... со мной сделал?', 24330),
(103440, 'ruRU', '', 'О нет!', 24330),
(103441, 'ruRU', '', 'Часовой! Уничтожь его, пока он не предупредил остальных!', 24330),
(103442, 'ruRU', '', 'Эредары призывают ещё демонов!', 24330),
(103443, 'ruRU', '', 'Маги порталов! Уберите их, пока они не привели подкрепление!', 24330),
(103445, 'ruRU', '', 'Магия портала эредаров поразила меня... Мне нужна минутка, чтобы оправиться.', 24330),
(103446, 'ruRU', '', 'То строение вдали, должно быть, собор. Веди, я с тобой!', 24330),
(103447, 'ruRU', '', 'Наша миссия имеет критическую важность!', 24330),
(103452, 'ruRU', '', 'Эта функция ещё не готова к тестированию. Вам засчитано выполнение этой цели.', 24330),
(103455, 'ruRU', '', 'Это потрясающе! Подумай, сколько всего мы могли бы узнать из этих фолиантов!', 24330),
(103456, 'ruRU', '', 'Не говоря уже о силе, которую они могли бы нам дать...', 24330),
(103462, 'ruRU', '', 'Едва ли больше, чем на один укус, но, полагаю, сойдёшь и ты!', 24330),
(103463, 'ruRU', '', 'Но... кто покормит моих милых?', 24330),
(103464, 'ruRU', '', 'Ты как раз вовремя к ужину... для моих питомцев, я имею в виду!', 24330),
(103488, 'ruRU', '', 'Король Андуин, герой Расколотого берега приближается.', 24330),
(103490, 'ruRU', '', 'Мои секреты Скверны поглотят тебя!', 24330);
